   "      </div>\n    </div>\n    <button class=\"secondary\" style=\"width:100%; margin-top:10px; color:var(--urgente);\" onclick=\"regenerarEnlaceEstudiantesLaboratorioUI()\">Generar un enlace nuevo (invalida el anterior)</button>\n    <div id=\"est_lab\" style=\"margin-top:24px;\"></div>\n  `;\n  abrirModal(true);\n  est_cargar();\n}\n\n// ---------- Base de estudiantes registrados ----------\n// Editar, bloquear, borrar, vigencia por meses (con aviso 7 días antes y el\n// día que vence) y alta como cliente en Microsip.\n\nlet EST = { lista: [], filtro: 'todos', q: '', abierto: null, modo: null, similares: null, msg: '', avisos: {} };\n\nasync function est_cargar() {\n  const caja = document.getElementById('est_lab');\n  if (!caja) return;\n  try {\n    const r = await api('/api/laboratorio/estudiantes');\n    EST.lista = r.estudiantes; EST.avisos = r.avisos || {};\n  } catch (e) {\n    caja.innerHTML = `<div class=\"error-msg\">${escapeHtml(e.message)}</div>`;\n    return;\n  }\n  est_render();\n}\n\nfunction est_badgeVigencia(e) {\n  const estilos = { vigente: ['#4caf50', `Vigente hasta ${e.vigencia_hasta}`], por_vencer: ['#e8a33d', e.vigencia_dias === 0 ? 'Vence HOY' : `Vence en ${e.vigencia_dias} día(s) · ${e.vigencia_hasta}`],\n                    vencida: ['var(--urgente)', `Vencida (${e.vigencia_hasta})`], sin_vigencia: ['var(--muted)', 'Sin vigencia (sin límite)'] };\n  const [color, texto] = estilos[e.vigencia_estado] || estilos.sin_vigencia;\n  return `<span style=\"font-size:11px; font-weight:700; color:${color};\">${escapeHtml(texto)}</span>`;\n}\n\nfunction est_filtrados() {\n  const q = EST.q.trim().toLowerCase();\n  return EST.lista.filter(e => {\n    if (EST.filtro === 'por_vencer' && e.vigencia_estado !== 'por_vencer') return false;\n    if (EST.filtro === 'vencidos' && e.vigencia_estado !== 'vencida') return false;\n    if (EST.filtro === 'bloqueados' && e.activo) return false;\n    if (!q) return true;\n    return [e.matricula, e.nombre_completo, e.email, e.telefono].some(v => (v || '').toLowerCase().includes(q));\n  });\n}\n\nfunction est_render() {\n  const caja = document.getElementById('est_lab');\n  if (!caja) return;\n  cv_asegurarEstilos();\n  const lista = est_filtrados();\n  const cuenta = k => EST.lista.filter(e => k === 'por_vencer' ? e.vigencia_estado === 'por_vencer' : k === 'vencidos' ? e.vigencia_estado === 'vencida' : k === 'bloqueados' ? !e.activo : true).length;\n  const filtro = (k, t) => `<button class=\"${EST.filtro === k ? 'primary' : 'secondary'}\" style=\"padding:6px 10px; font-size:12px;\" onclick=\"EST.filtro='${k}'; est_render()\">${t} (${cuenta(k)})</button>`;\n  caja.innerHTML = `\n    <h3 style=\"margin:0 0 6px;\">🎓 Estudiantes registrados</h3>\n    <p style=\"font-size:12px; color:var(--muted); margin:0 0 8px;\">Con la vigencia vencida o bloqueado, el estudiante no puede entrar (se le pide actualizar su información en sucursal). Se le avisa 7 días antes y el día que vence\n      ${EST.avisos.correo ? '· ✉️ correo activo' : '· ✉️ correo <b>sin configurar</b> (SMTP en Render)'} ${EST.avisos.push ? '· 📱 push activo' : '· 📱 push <b>sin configurar</b> (Firebase en Render)'}.</p>\n    ${EST.msg ? `<div style=\"font-size:13px; margin:6px 0;\">${EST.msg}</div>` : ''}\n    <div style=\"display:flex; gap:6px; flex-wrap:wrap; margin-bottom:8px;\">${filtro('todos', 'Todos')}${filtro('por_vencer', 'Por vencer')}${filtro('vencidos', 'Vencidos')}${filtro('bloqueados', 'Bloqueados')}</div>\n    <input placeholder=\"Buscar por matrícula, nombre, correo o teléfono\" value=\"${escapeHtml(EST.q)}\" oninput=\"EST.q=this.value; est_renderLista()\" style=\"margin-bottom:8px;\" />\n    <div id=\"est_lista\"></div>`;\n  est_renderLista();\n}\n\nfunction est_renderLista() {\n  const cont = document.getElementById('est_lista');\n  if (!cont) return;\n  const lista = est_filtrados();\n  cont.innerHTML = lista.length ? lista.map(e => `\n    <div class=\"cv-caja\" style=\"margin-bottom:8px; ${e.activo ? '' : 'opacity:0.75;'}\">\n      <div style=\"display:flex; justify-content:space-between; gap:8px; flex-wrap:wrap;\">\n        <div style=\"min-width:200px; flex:1;\">\n          <b>${escapeHtml(e.nombre_completo)}</b> <span style=\"font-family:monospace; color:var(--muted);\">${escapeHtml(e.matricula)}</span>\n          ${e.activo ? '' : ' <span style=\"font-size:11px; font-weight:700; color:var(--urgente);\">🔒 BLOQUEADO</span>'}<br>\n          <span style=\"font-size:12px; color:var(--muted);\">${escapeHtml(e.email || 'sin correo')} · ${escapeHtml(e.telefono || 'sin teléfono')} · ${e.trabajos} pedido(s)${e.tiene_app ? ' · 📱 app' : ''}${e.microsip_cliente_id ? ` · Microsip #${e.microsip_cliente_id}` : ''}</span><br>\n          ${est_badgeVigencia(e)}\n        </div>\n        <div style=\"display:flex; gap:4px; flex-wrap:wrap; align-items:flex-start;\">\n          <button class=\"secondary\" style=\"padding:5px 9px; font-size:12px;\" onclick=\"est_abrir(${e.id}, 'editar')\">✏️ Editar</button>\n          <button class=\"secondary\" style=\"padding:5px 9px; font-size:12px;\" onclick=\"est_abrir(${e.id}, 'vigencia')\">📅 Vigencia</button>\n          <button class=\"secondary\" style=\"padding:5px 9px; font-size:12px;\" onclick=\"est_bloquear(${e.id}, ${e.activo})\">${e.activo ? '🔒 Bloquear' : '🔓 Desbloquear'}</button>\n          <button class=\"secondary\" style=\"padding:5px 9px; font-size:12px;\" onclick=\"est_microsip(${e.id}, {})\">${e.microsip_cliente_id ? '🧾 Microsip ✔' : '🧾 Alta Microsip'}</button>\n          <button class=\"secondary\" style=\"padding:5px 9px; font-size:12px; color:var(--urgente);\" onclick=\"est_borrar(${e.id})\">🗑</button>\n        </div>\n      </div>\n      ${EST.abierto === e.id ? est_panel(e) : ''}\n    </div>`).join('') : '<p style=\"font-size:13px; color:var(--muted);\">No hay estudiantes con ese filtro.</p>';\n}\n\nfunction est_panel(e) {\n  if (EST.modo === 'editar') {\n    return `<div style=\"margin-top:10px; border-top:1px solid rgba(155,157,159,0.3); padding-top:10px;\">\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Matrícula</label><input id=\"est_mat\" value=\"${escapeHtml(e.matricula)}\" /></div>\n        <div class=\"field\"><label>Nombre completo</label><input id=\"est_nom\" value=\"${escapeHtml(e.nombre_completo)}\" /></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Correo</label><input id=\"est_email\" type=\"email\" value=\"${escapeHtml(e.email || '')}\" /></div>\n        <div class=\"field\"><label>Teléfono</label><input id=\"est_tel\" value=\"${escapeHtml(e.telefono || '')}\" /></div>\n      </div>\n      <div class=\"field\"><label>Nueva contraseña (vacío = no cambiarla)</label><input id=\"est_pass\" type=\"password\" autocomplete=\"new-password\" /></div>\n      <div style=\"display:flex; gap:6px;\"><button class=\"primary\" style=\"flex:1;\" onclick=\"est_guardar(${e.id}, this)\">Guardar</button><button class=\"secondary\" onclick=\"EST.abierto=null; est_renderLista()\">Cancelar</button></div>\n    </div>`;\n  }\n  if (EST.modo === 'vigencia') {\n    const b = m => `<button class=\"secondary\" style=\"padding:6px 10px;\" onclick=\"est_vigencia(${e.id}, { meses: ${m} })\">+${m} ${m === 1 ? 'mes' : 'meses'}</button>`;\n    return `<div style=\"margin-top:10px; border-top:1px solid rgba(155,157,159,0.3); padding-top:10px;\">\n      <p style=\"font-size:12px; color:var(--muted); margin:0 0 6px;\">Los meses se suman desde hoy, o desde su vigencia actual si todavía no vence.</p>\n      <div style=\"display:flex; gap:6px; flex-wrap:wrap; margin-bottom:8px;\">${[1, 3, 6, 12].map(b).join('')}</div>\n      <div style=\"display:flex; gap:6px; align-items:center; flex-wrap:wrap;\">\n        <input type=\"date\" id=\"est_hasta\" value=\"${escapeHtml(e.vigencia_hasta || '')}\" style=\"max-width:180px;\" />\n        <button class=\"secondary\" onclick=\"est_vigencia(${e.id}, { hasta: document.getElementById('est_hasta').value })\">Poner esta fecha</button>\n        <button class=\"secondary\" onclick=\"est_vigencia(${e.id}, { quitar: true })\">Sin límite</button>\n        ${e.vigencia_hasta ? `<button class=\"secondary\" onclick=\"est_avisar(${e.id}, this)\">📣 Mandar aviso ahora</button>` : ''}\n      </div>\n    </div>`;\n  }\n  if (EST.modo === 'microsip' && EST.similares) {\n    return `<div style=\"margin-top:10px; border-top:1px solid rgba(155,157,159,0.3); padding-top:10px;\">\n      <p style=\"font-size:13px; margin:0 0 6px;\">Encontré clientes parecidos en Microsip. ¿Es alguno?</p>\n      ${EST.similares.map(c => `<div style=\"display:flex; justify-content:space-between; gap:8px; align-items:center; font-size:12px; padding:4px 0;\">\n        <span><b>${escapeHtml(c.nombre)}</b>${c.clave ? ` · clave ${escapeHtml(c.clave)}` : ''} · ${escapeHtml([c.rfc, c.telefono].filter(Boolean).join(' · ') || '—')}<br><span style=\"color:#e8a33d;\">${(c.motivos || []).map(escapeHtml).join(' · ')}</span></span>\n        <button class=\"primary\" style=\"padding:5px 10px;\" onclick=\"est_microsip(${e.id}, { microsip_cliente_id: ${Number(c.cliente_id)} })\">Es este</button></div>`).join('')}\n      <button class=\"secondary\" style=\"width:100%; margin-top:6px;\" onclick=\"est_microsip(${e.id}, { nuevo: true })\">➕ Ninguno — darlo de alta nuevo</button>\n    </div>`;\n  }\n  return '';\n}\n\nfunction est_abrir(id, modo) {\n  if (EST.abierto === id && EST.modo === modo) { EST.abierto = null; } else { EST.abierto = id; EST.modo = modo; }\n  EST.msg = '';\n  est_renderLista();\n}\n\nfunction est_reemplazar(e) {\n  EST.lista = EST.lista.map(x => x.id === e.id ? e : x);\n}\n\nasync function est_guardar(id, btn) {\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      const cuerpo = { matricula: document.getElementById('est_mat').value.trim(), nombre_completo: document.getElementById('est_nom').value.trim(),\n                       email: document.getElementById('est_email').value.trim(), telefono: document.getElementById('est_tel').value.trim() };\n      const pass = document.getElementById('est_pass').value;\n      if (pass) cuerpo.password = pass;\n      est_reemplazar(await api(`/api/laboratorio/estudiantes/${id}`, { method: 'PATCH', body: JSON.stringify(cuerpo) }));\n      EST.abierto = null; EST.msg = '<span style=\"color:#4caf50;\">✔ Guardado.</span>';\n      est_render();\n    } catch (e) { alert(e.message); }\n  });\n}\n\nasync function est_vigencia(id, cuerpo) {\n  if (cuerpo.hasta === '') { alert('Elige una fecha.'); return; }\n  try {\n    const e = await api(`/api/laboratorio/estudiantes/${id}/vigencia`, { method: 'POST', body: JSON.stringify(cuerpo) });\n    est_reemplazar(e); EST.abierto = null;\n    EST.msg = `<span style=\"color:#4caf50;\">✔ ${escapeHtml(e.nombre_completo)}: ${e.vigencia_hasta ? 'vigente hasta ' + escapeHtml(e.vigencia_hasta) : 'sin límite de vigencia'}.</span>`;\n    est_render();\n  } catch (e) { alert(e.message); }\n}\n\nasync function est_bloquear(id, activo) {\n  const e0 = EST.lista.find(x => x.id === id);\n  if (activo && !confirm(`¿Bloquear a ${e0.nombre_completo}? Ya no podrá entrar a la app ni al portal.`)) return;\n  try {\n    est_reemplazar(await api(`/api/laboratorio/estudiantes/${id}/bloquear`, { method: 'POST', body: JSON.stringify({ bloqueado: activo }) }));\n    EST.msg = ''; est_render();\n  } catch (e) { alert(e.message); }\n}\n\nasync function est_borrar(id) {\n  const e0 = EST.lista.find(x => x.id === id);\n  if (!confirm(`¿Borrar la cuenta de ${e0.nombre_completo} (${e0.matricula})? No se puede deshacer.`)) return;\n  try {\n    await api(`/api/laboratorio/estudiantes/${id}`, { method: 'DELETE' });\n    EST.lista = EST.lista.filter(x => x.id !== id);\n    EST.msg = '<span style=\"color:#4caf50;\">✔ Cuenta borrada.</span>';\n    est_render();\n  } catch (e) { alert(e.message); }\n}\n\nasync function est_microsip(id, cuerpo) {\n  const e0 = EST.lista.find(x => x.id === id);\n  if (e0.microsip_cliente_id && !cuerpo.microsip_cliente_id && !cuerpo.nuevo\n      && !confirm(`${e0.nombre_completo} ya está ligado al cliente #${e0.microsip_cliente_id} de Microsip. ¿Buscarlo de nuevo?`)) return;\n  EST.msg = '⏳ Consultando Microsip…'; est_render();\n  try {\n    const r = await api(`/api/laboratorio/estudiantes/${id}/microsip`, { method: 'POST', body: JSON.stringify(cuerpo) });\n    if (r.estado === 'elegir_cliente') {\n      EST.abierto = id; EST.modo = 'microsip'; EST.similares = r.similares; EST.msg = '';\n    } else {\n      est_reemplazar(r.estudiante); EST.abierto = null; EST.similares = null;\n      EST.msg = `<span style=\"color:#4caf50;\">✔ ${r.cliente_creado ? 'Dado de alta' : 'Ligado'} en Microsip: ${escapeHtml(r.cliente_nombre)}${r.cliente_clave ? ` (clave ${escapeHtml(r.cliente_clave)})` : ''}${r.campos_completados && r.campos_completados.length ? ` — se completó: ${escapeHtml(r.campos_completados.join(', '))}` : ''}.</span>`\n        + (r.avisos || []).map(a => `<br><span style=\"color:#e8a33d;\">⚠️ ${escapeHtml(a)}</span>`).join('');\n    }\n  } catch (e) { EST.msg = `<span style=\"color:var(--urgente);\">⚠️ ${escapeHtml(e.message)}</span>`; }\n  est_render();\n}\n\nasync function est_avisar(id, btn) {\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      const r = await api(`/api/laboratorio/estudiantes/${id}/avisar-vigencia`, { method: 'POST' });\n      alert(`Aviso enviado — push: ${r.push ? 'sí' : 'no'} · correo: ${r.correo ? 'sí' : 'no'}` + (!r.push && !r.correo ? '\\n\\nRevisa que estén configurados el correo (SMTP) y/o Firebase en Render, y que el estudiante tenga correo o la app instalada.' : ''));\n    } catch (e) { alert(e.message); }\n  });\n}\n\nfunction copiarEnlaceEstudiantesLaboratorio() {\n"
