   "  #firmaCanvas { width:100%; height:120px; background:#0F1011; border:1px solid rgba(155,157,159,0.3); border-radius:var(--radius); touch-action:none; cursor:crosshair; }\n  #pantallaInvalida { display:none; text-align:center; padding:60px 20px; color:#C4C6C9; }\n  .hidden { display:none !important; }\n  /* Pedido paso a paso (Restauración → Corona → posición → parámetros) */\n  .pasos { display:flex; gap:6px; margin:-4px 0 14px; }\n  .pasos span { flex:1; height:4px; border-radius:4px; background:rgba(155,157,159,0.25); }\n  .pasos span.on { background:var(--copper); }\n  .opcion-grande { display:flex; flex-direction:column; align-items:stretch; gap:10px; width:100%; text-align:left; padding:14px; border-radius:var(--radius-lg); background:#111213; border:1px solid rgba(155,157,159,0.25); color:#EDEDED; }\n  .opcion-grande:active { transform:translateY(1px); }\n  .opcion-grande .ilustracion { background:#F4F4F4; border-radius:var(--radius); height:150px; display:flex; align-items:center; justify-content:center; }\n  .opcion-grande .titulo { font-size:17px; font-weight:600; }\n  .chips { display:flex; flex-wrap:wrap; gap:8px; }\n  .chip { display:flex; align-items:center; gap:8px; padding:12px 16px; border-radius:var(--radius); background:#111213; border:1px solid rgba(155,157,159,0.3); color:#EDEDED; font-weight:600; }\n  .chip.on { border-color:var(--copper); background:rgba(216,25,47,0.14); color:#fff; }\n  .odonto { overflow-x:auto; padding-bottom:6px; }\n  .odonto-fila { display:grid; grid-template-columns:repeat(16, minmax(30px, 1fr)); gap:4px; min-width:520px; margin-bottom:4px; }\n  .diente { display:flex; flex-direction:column; align-items:center; gap:2px; padding:6px 0 4px; border-radius:7px; background:#F4F4F4; border:2px solid transparent; color:#222; font-size:11px; font-weight:700; cursor:pointer; user-select:none; }\n  .diente svg { width:20px; height:30px; }\n  .diente.on { border-color:var(--copper); background:#FFE3E6; }\n  .diente.inferior { flex-direction:column-reverse; }\n  .odonto-sep { height:1px; background:rgba(155,157,159,0.35); margin:6px 0 8px; min-width:520px; }\n  .resumen-total { display:flex; justify-content:space-between; align-items:center; font-size:15px; padding:12px 0 4px; border-top:1px solid rgba(155,157,159,0.2); margin-top:6px; }\n  .resumen-total b { font-family:'JetBrains Mono',monospace; color:var(--copper-light); font-size:18px; }\n  .aviso-vigencia { border-radius:var(--radius); padding:12px 14px; margin-bottom:14px; font-size:13px; background:rgba(240,167,35,0.14); color:#F0C36D; border:1px solid rgba(240,167,35,0.4); }\n</style>\n</head>\n<body>\n"
