NUEVOS = {
 "backend/correo.py": "\"\"\"\nEnvío de correos por SMTP (para avisos a estudiantes, por ejemplo que su\nvigencia está por vencer).\n\nVariables de entorno (Render → Environment):\n  SMTP_HOST      ej. smtp.gmail.com\n  SMTP_PORT      587 (STARTTLS) o 465 (SSL). Default 587.\n  SMTP_USER      la cuenta, ej. laboratorio@markinc.com.mx\n  SMTP_PASSWORD  con Gmail/Google Workspace: una \"contraseña de aplicación\"\n  SMTP_FROM      opcional, ej. \"Markinc Lab <laboratorio@markinc.com.mx>\"\n\nSi no están, configurado() es False y enviar() no hace nada (nunca truena\nel flujo que lo llama).\n\"\"\"\nimport os\nimport smtplib\nimport ssl\nfrom email.message import EmailMessage\nfrom email.utils import formataddr, parseaddr\n\n\ndef configurado():\n    return bool(os.getenv(\"SMTP_HOST\") and os.getenv(\"SMTP_USER\") and os.getenv(\"SMTP_PASSWORD\"))\n\n\ndef enviar(destinatario, asunto, texto):\n    \"\"\"True si se mandó; False si no hay SMTP o falló (se registra en consola).\"\"\"\n    if not configurado() or not destinatario or \"@\" not in destinatario:\n        return False\n    host = os.getenv(\"SMTP_HOST\")\n    puerto = int(os.getenv(\"SMTP_PORT\") or 587)\n    usuario = os.getenv(\"SMTP_USER\")\n    remitente = os.getenv(\"SMTP_FROM\") or usuario\n    nombre, direccion = parseaddr(remitente)\n    msg = EmailMessage()\n    msg[\"From\"] = formataddr((nombre, direccion or usuario)) if nombre else (direccion or usuario)\n    msg[\"To\"] = destinatario\n    msg[\"Subject\"] = asunto\n    msg.set_content(texto)\n    try:\n        contexto = ssl.create_default_context()\n        if puerto == 465:\n            with smtplib.SMTP_SSL(host, puerto, context=contexto, timeout=20) as s:\n                s.login(usuario, os.getenv(\"SMTP_PASSWORD\"))\n                s.send_message(msg)\n        else:\n            with smtplib.SMTP(host, puerto, timeout=20) as s:\n                s.starttls(context=contexto)\n                s.login(usuario, os.getenv(\"SMTP_PASSWORD\"))\n                s.send_message(msg)\n        return True\n    except Exception as e:\n        print(f\"[correo] no se pudo mandar a {destinatario}: {e}\")\n        return False\n",
 "backend/push_notifications.py": "\"\"\"\nNotificaciones push a la app Android de estudiantes (Firebase Cloud\nMessaging). Requiere la variable FIREBASE_SERVICE_ACCOUNT_JSON en Render con\nel contenido completo de la clave de cuenta de servicio (Firebase Console →\nConfiguración del proyecto → Cuentas de servicio → Generar nueva clave).\nSi falta, configurado() es False y enviar() no hace nada.\n\"\"\"\nimport json\nimport os\n\n_app = None\n\n\ndef configurado():\n    return bool(os.getenv(\"FIREBASE_SERVICE_ACCOUNT_JSON\"))\n\n\ndef _iniciar():\n    global _app\n    if _app is None:\n        import firebase_admin\n        from firebase_admin import credentials\n        cred = credentials.Certificate(json.loads(os.getenv(\"FIREBASE_SERVICE_ACCOUNT_JSON\")))\n        _app = firebase_admin.initialize_app(cred, name=\"markinc-lab\")\n    return _app\n\n\ndef enviar(token, titulo, cuerpo, datos=None):\n    \"\"\"True si Firebase aceptó el mensaje.\"\"\"\n    if not configurado() or not token:\n        return False\n    try:\n        from firebase_admin import messaging\n        mensaje = messaging.Message(\n            token=token,\n            notification=messaging.Notification(title=titulo, body=cuerpo),\n            data={k: str(v) for k, v in (datos or {}).items()},\n        )\n        messaging.send(mensaje, app=_iniciar())\n        return True\n    except Exception as e:\n        print(f\"[push] no se pudo mandar: {e}\")\n        return False\n"
}


def main():
    errores = []
    cambios = {}
    for ruta, contenido in NUEVOS.items():
        if os.path.exists(ruta):
            with open(ruta, encoding="utf-8") as f:
                actual = f.read().replace("\r\n", "\n")
            if actual == contenido:
                continue
        cambios[ruta] = contenido
    for ruta, pares in ARCHIVOS.items():
        if not os.path.exists(ruta):
            errores.append(f"No encontre {ruta} -- corre el script desde la carpeta del repo.")
            continue
        with open(ruta, encoding="utf-8", newline="") as f:
            original = f.read()
        # Windows: el archivo puede tener saltos CRLF, LF o una mezcla.
        # Se trabaja todo en LF y al guardar se deja como estaba (CRLF si tenia).
        crlf = "\r\n" in original
        texto = original.replace("\r\n", "\n")
        inicial = texto
        for i, (viejo, nuevo) in enumerate(pares, 1):
            if nuevo in texto:
                continue  # ya aplicado
            n = texto.count(viejo)
            if n != 1:
                errores.append(f"{ruta}: cambio #{i} -- el texto a reemplazar aparece {n} veces (se esperaba 1).")
                continue
            texto = texto.replace(viejo, nuevo, 1)
        if texto != inicial:
            cambios[ruta] = texto.replace("\n", "\r\n") if crlf else texto
    if errores:
        print("NO se aplico nada:")
        for e in errores:
            print("  -", e)
        sys.exit(1)
    for ruta, texto in cambios.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("Actualizado:", ruta)
    if not cambios:
        print("Todo ya estaba aplicado, no hubo cambios.")
    else:
        print("Listo.")


if __name__ == "__main__":
    main()
